/**
 * BusinessProcessArtifact
 *
 * Input or output artifact for a business process
 */
export type BusinessProcessArtifact = {
    /**
     * Model Name
     */
    model_name: string;
    /**
     * Business Friendly Name
     */
    business_friendly_name: string;
    /**
     * External Description
     */
    external_description: string;
    /**
     * Source Process
     */
    source_process?: string | null;
};

/**
 * BusinessProcessTask
 *
 * Individual task within a business process
 */
export type BusinessProcessTask = {
    /**
     * Task Number
     */
    task_number: number;
    /**
     * Description
     */
    description: string;
    /**
     * Branch Type
     */
    branch_type?: string | null;
    /**
     * User Has Permission
     */
    user_has_permission: boolean;
    /**
     * Permission Display
     */
    permission_display?: string;
};

/**
 * OutputBusinessProcess
 *
 * Business process details with all tasks
 */
export type OutputBusinessProcess = {
    /**
     * Process Name
     */
    process_name: string;
    /**
     * Description
     */
    description: string;
    /**
     * Tasks
     */
    tasks: Array<BusinessProcessTask>;
    /**
     * Input Artifacts
     */
    input_artifacts: Array<BusinessProcessArtifact>;
    /**
     * Modification Artifacts
     */
    modification_artifacts: Array<BusinessProcessArtifact>;
    /**
     * Output Artifacts
     */
    output_artifacts: Array<BusinessProcessArtifact>;
    /**
     * Highlight Task
     */
    highlight_task?: number | null;
};

